     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	
     6	public final class Money {
     7	    public static final BigDecimal ZERO = new BigDecimal("0.00");
     8	
     9	    private Money() {}
    10	
    11	    public static BigDecimal of(String value) { return round(new BigDecimal(value)); }
    12	
    13	    public static BigDecimal round(BigDecimal value) { return value.setScale(2, RoundingMode.HALF_EVEN); }
    14	
    15	    /** Formato dos comprovantes: R$ 1.234,56 */
    16	    public static String format(BigDecimal value) {
    17	        String plain = round(value).toPlainString();
    18	        int dot = plain.indexOf('.');
    19	        String integer = plain.substring(0, dot);
    20	        String cents = plain.substring(dot + 1);
    21	        StringBuilder grouped = new StringBuilder();
    22	        int digits = integer.length();
    23	        for (int i = 0; i < digits; i++) {
    24	            grouped.append(integer.charAt(i));
    25	            int remaining = digits - i - 1;
    26	            if (remaining > 0 && remaining % 3 == 0) grouped.append('.');
    27	        }
    28	        return "R$ " + grouped + "," + cents;
    29	    }
    30	}
