     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.format.DateTimeFormatter;
     6	
     7	public record Receipt(String title, int reservationId, String guestName, String guestCpf, int roomNumber,
     8	                      RoomType roomType, LocalDate checkIn, LocalDate checkOut, int nights, BigDecimal subtotal,
     9	                      BigDecimal discount, BigDecimal total) {
    10	    public static final String TITLE = "Comprovante de reserva";
    11	    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    12	
    13	    public static Receipt of(Reservation r) {
    14	        return new Receipt(TITLE, r.id(), r.guestName(), r.guestCpf(), r.room().number(), r.room().type(),
    15	                r.checkInDate(), r.checkOutDate(), r.nights(), r.subtotal(), r.discount(), r.total());
    16	    }
    17	
    18	    public String text() {
    19	        StringBuilder sb = new StringBuilder();
    20	        sb.append(title).append(" nº ").append(reservationId).append('\n');
    21	        sb.append("Hóspede: ").append(guestName).append(" (CPF ").append(formatCpf(guestCpf)).append(")\n");
    22	        sb.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    23	        sb.append("Entrada: ").append(DATE.format(checkIn)).append(" | Saída: ").append(DATE.format(checkOut))
    24	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    25	        sb.append("Diárias: ").append(Money.format(subtotal)).append('\n');
    26	        if (discount.signum() > 0) {
    27	            sb.append("Desconto: ").append(Money.format(discount)).append('\n');
    28	        }
    29	        sb.append("Total: ").append(Money.format(total));
    30	        return sb.toString();
    31	    }
    32	
    33	    private static String formatCpf(String cpf) {
    34	        if (cpf.matches("\\d{11}")) {
    35	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
    36	        }
    37	        return cpf;
    38	    }
    39	}
