     1	package br.com.mare.domain;
     2	
     3	import br.com.mare.infra.Db;
     4	import br.com.mare.infra.ReservationRepository;
     5	
     6	import java.math.BigDecimal;
     7	import java.time.LocalDate;
     8	import java.time.YearMonth;
     9	import java.util.List;
    10	
    11	public class ReportService {
    12	    private final Db db;
    13	    private final ReservationRepository reservations;
    14	
    15	    public ReportService(Db db, ReservationRepository reservations) {
    16	        this.db = db;
    17	        this.reservations = reservations;
    18	    }
    19	
    20	    public String occupancy(LocalDate night) {
    21	        List<Reservation> list = db.transaction(c -> reservations.findPaidOccupying(c, night));
    22	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    23	        for (Reservation r : list) {
    24	            csv.append(r.room().number()).append(',').append(r.room().type()).append(',').append(r.id()).append(',')
    25	                    .append(r.checkInDate()).append(',').append(r.checkOutDate()).append('\n');
    26	        }
    27	        long rooms = list.stream().map(r -> r.room().number()).distinct().count();
    28	        return csv.append("total,").append(rooms).append('/').append(Rooms.all().size()).append('\n').toString();
    29	    }
    30	
    31	    public String revenue(YearMonth month) {
    32	        List<Reservation> list = db.transaction(c ->
    33	                reservations.findWithRevenueStartingBetween(c, month.atDay(1), month.plusMonths(1).atDay(1)));
    34	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    35	        BigDecimal sum = Money.ZERO;
    36	        for (Reservation r : list) {
    37	            csv.append(r.id()).append(',').append(r.room().number()).append(',').append(r.checkInDate()).append(',')
    38	                    .append(r.checkOutDate()).append(',').append(r.status()).append(',')
    39	                    .append(r.netRevenue().toPlainString()).append('\n');
    40	            sum = sum.add(r.netRevenue());
    41	        }
    42	        return csv.append("total,").append(Money.round(sum).toPlainString()).append('\n').toString();
    43	    }
    44	}
