    20	    private final BigDecimal discount;
    21	    private final BigDecimal total;
    22	    private Status status;
    23	    private BigDecimal amountPaid;
    24	    private BigDecimal refund;
    25	
    26	    public Reservation(int id, Room room, String guestName, String guestEmail, String guestCpf, LocalDate checkIn,
    27	                       LocalDate checkOut, int guests, RatePlan ratePlan, int nights, BigDecimal subtotal,
    28	                       BigDecimal discount, BigDecimal total, Status status, BigDecimal amountPaid, BigDecimal refund) {
    29	        this.id = id;
    30	        this.room = room;
    31	        this.guestName = guestName;
    32	        this.guestEmail = guestEmail;
    33	        this.guestCpf = guestCpf;
    34	        this.checkIn = checkIn;
    35	        this.checkOut = checkOut;
    36	        this.guests = guests;
    37	        this.ratePlan = ratePlan;
    38	        this.nights = nights;
    39	        this.subtotal = subtotal;
    40	        this.discount = discount;
    41	        this.total = total;
    42	        this.status = status;
    43	        this.amountPaid = amountPaid;
    44	        this.refund = refund;
    45	    }
    46	
    47	    public void confirm() {
    48	        requireStatus("confirmar", Status.PENDING);
    49	        status = Status.CONFIRMED;
    50	        amountPaid = total;
    51	    }
    52	
    53	    public void checkIn() {
    54	        requireStatus("fazer o check-in de", Status.CONFIRMED);
    55	        status = Status.CHECKED_IN;
    56	    }
    57	
    58	    public void checkOut() {
    59	        requireStatus("fazer o check-out de", Status.CHECKED_IN);
    60	        status = Status.CHECKED_OUT;
    61	    }
    62	
    63	    public void cancel() {
    64	        requireStatus("cancelar", Status.PENDING, Status.CONFIRMED);
    65	        refund = ratePlan.refund(amountPaid);
    66	        status = Status.CANCELLED;
    67	    }
    68	
    69	    public void requirePaid() {
    70	        if (!status.isPaid()) {
    71	            throw ApiException.notAllowed("Só existe comprovante para reserva paga; situação atual: " + status);
    72	        }
    73	    }
    74	
    75	    private void requireStatus(String action, Status... allowed) {
    76	        for (Status s : allowed) {
    77	            if (s == status) return;
    78	        }
    79	        throw ApiException.notAllowed("Não é possível " + action + " uma reserva " + status);
    80	    }
