     1	package br.com.mare.domain;
     2	
     3	import br.com.mare.infra.Db;
     4	import br.com.mare.infra.MessageRepository;
     5	import br.com.mare.infra.ReservationRepository;
     6	import br.com.mare.plan.Booking;
     7	import br.com.mare.plan.Quote;
     8	import br.com.mare.plan.RatePlan;
     9	import br.com.mare.plan.RatePlans;
    10	
    11	import java.sql.Connection;
    12	import java.sql.SQLException;
    13	import java.sql.Statement;
    14	import java.util.List;
    15	import java.util.function.Consumer;
    16	
    17	public class ReservationService {
    18	    static final String CONFIRMATION_SUBJECT = "Reserva confirmada - Pousada Maré Alta";
    19	
    20	    private final Db db;
    21	    private final ReservationRepository reservations;
    22	    private final MessageRepository messages;
    23	
    24	    public ReservationService(Db db, ReservationRepository reservations, MessageRepository messages) {
    25	        this.db = db;
    26	        this.reservations = reservations;
    27	        this.messages = messages;
    28	    }
    29	
    30	    public Reservation create(ReservationRequest req) {
    31	        Room room = Rooms.find(req.roomNumber())
    32	                .orElseThrow(() -> ApiException.roomNotFound("Quarto " + req.roomNumber() + " não existe"));
    33	        if (req.guests() > room.capacity()) {
    34	            throw ApiException.capacityExceeded("O quarto " + room.number() + " comporta até " + room.capacity() + " pessoas");
    35	        }
    36	        RatePlan plan = RatePlans.find(req.ratePlan())
    37	                .orElseThrow(() -> ApiException.invalid("Plano de tarifa desconhecido: " + req.ratePlan()));
    38	        Quote quote = plan.quote(new Booking(room, req.checkIn(), req.checkOut(), req.companyCode()));
    39	
    40	        return db.transaction(c -> {
    41	            try (Statement s = c.createStatement()) {
    42	                s.execute("SELECT pg_advisory_xact_lock(2)");
    43	            }
    44	            if (reservations.hasConflict(c, room.number(), req.checkIn(), req.checkOut())) {
    45	                throw ApiException.roomUnavailable("O quarto " + room.number() + " já está reservado em alguma das noites");
    46	            }
    47	            Reservation draft = new Reservation(0, room, req.guestName(), req.guestEmail(), req.guestCpf(),
    48	                    req.checkIn(), req.checkOut(), req.guests(), plan, quote.nights(), quote.subtotal(),
    49	                    quote.discount(), quote.total(), Status.PENDING, Money.ZERO, null);
    50	            int id = reservations.insert(c, draft);
    51	            return reservations.find(c, id, false).orElseThrow();
    52	        });
    53	    }
    54	
    55	    public Reservation get(int id) {
    56	        return db.transaction(c -> load(c, id, false));
    57	    }
    58	
    59	    public Reservation confirm(int id) {
    60	        return change(id, Reservation::confirm, (c, r) -> {
    61	            String body = "Olá, " + r.guestName() + "!\n\n"
    62	                    + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
    63	                    + Receipt.of(r).text() + "\n\n"
    64	                    + "A entrada é a partir das 14h, e a saída, até as 12h.\nAté breve!";
    65	            messages.save(c, Message.EMAIL, r.guestEmail(), CONFIRMATION_SUBJECT, body);
    66	        });
    67	    }
    68	
    69	    public Reservation cancel(int id) { return change(id, Reservation::cancel, (c, r) -> {}); }
    70	
    71	    public Reservation checkIn(int id) { return change(id, Reservation::checkIn, (c, r) -> {}); }
    72	
    73	    public Receipt checkOut(int id) {
    74	        return Receipt.of(change(id, Reservation::checkOut, (c, r) -> {}));
    75	    }
    76	
    77	    public Receipt document(int id) {
    78	        Reservation r = get(id);
    79	        r.requirePaid();
    80	        return Receipt.of(r);
    81	    }
    82	
    83	    public List<Message> messages() {
    84	        return db.transaction(messages::findAll);
    85	    }
    86	
    87	    private interface SideEffect {
    88	        void run(Connection c, Reservation r) throws SQLException;
    89	    }
    90	
    91	    private Reservation change(int id, Consumer<Reservation> transition, SideEffect afterwards) {
    92	        return db.transaction(c -> {
    93	            Reservation r = load(c, id, true);
    94	            transition.accept(r);
    95	            reservations.updateState(c, r);
    96	            afterwards.run(c, r);
    97	            return r;
    98	        });
    99	    }
   100	
   101	    private Reservation load(Connection c, int id, boolean lock) throws SQLException {
   102	        return reservations.find(c, id, lock)
   103	                .orElseThrow(() -> ApiException.reservationNotFound("Reserva " + id + " não existe"));
   104	    }
   105	}
