     3	import java.sql.Connection;
     4	import java.sql.DriverManager;
     5	import java.sql.SQLException;
     6	import java.sql.Statement;
     7	
     8	public class Db {
     9	    private final String url;
    10	    private final String user;
    11	    private final String password;
    12	
    13	    public Db(String url, String user, String password) {
    14	        this.url = url;
    15	        this.user = user;
    16	        this.password = password;
    17	    }
    18	
    19	    public interface Work<T> {
    20	        T run(Connection connection) throws SQLException;
    21	    }
    22	
    23	    public <T> T transaction(Work<T> work) {
    24	        try (Connection c = DriverManager.getConnection(url, user, password)) {
    25	            c.setAutoCommit(false);
    26	            try {
    27	                T result = work.run(c);
    28	                c.commit();
    29	                return result;
    30	            } catch (Exception e) {
    31	                c.rollback();
    32	                throw e;
    33	            }
    34	        } catch (SQLException e) {
    35	            throw new IllegalStateException("Erro de banco de dados", e);
    36	        }
    37	    }
    38	
    39	    /** Cria o que o sistema precisa; espera o banco aceitar conexões. */
    40	    public void migrate() {
    41	        SQLException last = null;
    42	        for (int attempt = 0; attempt < 30; attempt++) {
    43	            try {
    44	                transaction(c -> {
    45	                    try (Statement s = c.createStatement()) {
    46	                        s.execute("SELECT pg_advisory_xact_lock(1)");
    47	                        s.execute("""
    48	                                CREATE TABLE IF NOT EXISTS reservations (
    49	                                  id SERIAL PRIMARY KEY,
    50	                                  room_number INT NOT NULL,
    51	                                  guest_name TEXT NOT NULL,
    52	                                  guest_email TEXT NOT NULL,
    53	                                  guest_cpf TEXT NOT NULL,
    54	                                  check_in DATE NOT NULL,
    55	                                  check_out DATE NOT NULL,
    56	                                  guests INT NOT NULL,
    57	                                  rate_plan TEXT NOT NULL,
    58	                                  nights INT NOT NULL,
    59	                                  subtotal NUMERIC(12,2) NOT NULL,
    60	                                  discount NUMERIC(12,2) NOT NULL,
    61	                                  total NUMERIC(12,2) NOT NULL,
    62	                                  status TEXT NOT NULL,
    63	                                  amount_paid NUMERIC(12,2) NOT NULL,
    64	                                  refund NUMERIC(12,2)
    65	                                )""");
    66	                        s.execute("""
    67	                                CREATE TABLE IF NOT EXISTS messages (
    68	                                  id SERIAL PRIMARY KEY,
    69	                                  channel TEXT NOT NULL,
    70	                                  recipient TEXT NOT NULL,
    71	                                  subject TEXT NOT NULL,
    72	                                  body TEXT NOT NULL
    73	                                )""");
    74	                    }
    75	                    return null;
    76	                });
    77	                return;
    78	            } catch (IllegalStateException e) {
    79	                if (!(e.getCause() instanceof SQLException se)) throw e;
    80	                last = se;
    81	                try { Thread.sleep(1000); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); }
    82	            }
    83	        }
    84	        throw new IllegalStateException("Banco indisponível", last);
    85	    }
    86	}
