    33	    public boolean hasConflict(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut) throws SQLException {
    34	        try (PreparedStatement ps = c.prepareStatement(
    35	                "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    36	                        + "AND check_in < ? AND check_out > ?")) {
    37	            ps.setInt(1, roomNumber);
    38	            ps.setDate(2, Date.valueOf(checkOut));
    39	            ps.setDate(3, Date.valueOf(checkIn));
    40	            try (ResultSet rs = ps.executeQuery()) {
