    60	            ps.setBigDecimal(10, r.subtotal());
    61	            ps.setBigDecimal(11, r.discount());
    62	            ps.setBigDecimal(12, r.total());
    63	            ps.setString(13, r.status().name());
    64	            ps.setBigDecimal(14, r.amountPaid());
    65	            ps.setBigDecimal(15, r.refund());
    66	            ps.executeUpdate();
    67	            try (ResultSet keys = ps.getGeneratedKeys()) {
