    86	    public List<Reservation> findPaidOccupying(Connection c, LocalDate night) throws SQLException {
    87	        return query(c, "WHERE status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') AND check_in <= ? AND check_out > ? "
    88	                + "ORDER BY room_number, id", Date.valueOf(night), Date.valueOf(night));
    89	    }
