    91	    /** Reservas que começam no período e deixaram dinheiro com a pousada. */
    92	    public List<Reservation> findWithRevenueStartingBetween(Connection c, LocalDate from, LocalDate toExclusive)
    93	            throws SQLException {
    94	        return query(c, "WHERE check_in >= ? AND check_in < ? AND amount_paid - COALESCE(refund, 0) > 0 "
    95	                + "ORDER BY check_in, id", Date.valueOf(from), Date.valueOf(toExclusive));
    96	    }
