    98	    private List<Reservation> query(Connection c, String where, Date... params) throws SQLException {
    99	        try (PreparedStatement ps = c.prepareStatement("SELECT " + COLUMNS + " FROM reservations " + where)) {
   100	            for (int i = 0; i < params.length; i++) ps.setDate(i + 1, params[i]);
   101	            try (ResultSet rs = ps.executeQuery()) {
   102	                List<Reservation> list = new ArrayList<>();
   103	                while (rs.next()) list.add(map(rs));
