    19	public class ReservationRepository {
    20	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    21	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
    22	
    23	    public Optional<Reservation> find(Connection c, int id, boolean lock) throws SQLException {
    24	        try (PreparedStatement ps = c.prepareStatement(
    25	                "SELECT " + COLUMNS + " FROM reservations WHERE id = ?" + (lock ? " FOR UPDATE" : ""))) {
    26	            ps.setInt(1, id);
    27	            try (ResultSet rs = ps.executeQuery()) {
    28	                return rs.next() ? Optional.of(map(rs)) : Optional.empty();
    29	            }
    30	        }
    31	    }
    32	
    33	    public boolean hasConflict(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut) throws SQLException {
    34	        try (PreparedStatement ps = c.prepareStatement(
    35	                "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    36	                        + "AND check_in < ? AND check_out > ?")) {
    37	            ps.setInt(1, roomNumber);
    38	            ps.setDate(2, Date.valueOf(checkOut));
    39	            ps.setDate(3, Date.valueOf(checkIn));
    40	            try (ResultSet rs = ps.executeQuery()) {
    41	                return rs.next();
    42	            }
    43	        }
    44	    }
    45	
    46	    public int insert(Connection c, Reservation r) throws SQLException {
    47	        try (PreparedStatement ps = c.prepareStatement(
    48	                "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    49	                        + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund) "
    50	                        + "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)", Statement.RETURN_GENERATED_KEYS)) {
    51	            ps.setInt(1, r.room().number());
    52	            ps.setString(2, r.guestName());
    53	            ps.setString(3, r.guestEmail());
    54	            ps.setString(4, r.guestCpf());
    55	            ps.setDate(5, Date.valueOf(r.checkInDate()));
    56	            ps.setDate(6, Date.valueOf(r.checkOutDate()));
    57	            ps.setInt(7, r.guests());
    58	            ps.setString(8, r.ratePlan().code());
    59	            ps.setInt(9, r.nights());
    60	            ps.setBigDecimal(10, r.subtotal());
    61	            ps.setBigDecimal(11, r.discount());
    62	            ps.setBigDecimal(12, r.total());
    63	            ps.setString(13, r.status().name());
    64	            ps.setBigDecimal(14, r.amountPaid());
    65	            ps.setBigDecimal(15, r.refund());
    66	            ps.executeUpdate();
    67	            try (ResultSet keys = ps.getGeneratedKeys()) {
    68	                keys.next();
    69	                return keys.getInt(1);
    70	            }
    71	        }
    72	    }
