    15	        validate(booking);
    16	        BigDecimal subtotal = Money.ZERO;
    17	        for (LocalDate night = booking.checkIn(); night.isBefore(booking.checkOut()); night = night.plusDays(1)) {
    18	            subtotal = Money.round(subtotal.add(booking.room().priceOn(night)));
    19	        }
    20	        BigDecimal discount = Money.round(subtotal.multiply(discountRate(booking)));
    21	        return new Quote(booking.nights(), subtotal, discount, Money.round(subtotal.subtract(discount)));
    22	    }
    23	
    24	    @Override
    25	    public BigDecimal refund(BigDecimal amountPaid) {
    26	        return Money.round(amountPaid.multiply(refundRate()));
    27	    }
