     1	package br.com.mare.web;
     2	
     3	import br.com.mare.domain.ApiException;
     4	import br.com.mare.domain.ReservationRequest;
     5	import com.fasterxml.jackson.databind.JsonNode;
     6	import com.fasterxml.jackson.databind.ObjectMapper;
     7	
     8	import java.time.LocalDate;
     9	import java.time.YearMonth;
    10	import java.time.format.DateTimeParseException;
    11	
    12	/** Lê e valida o formato dos dados que chegam do site. */
    13	final class RequestParser {
    14	    private static final ObjectMapper MAPPER = new ObjectMapper();
    15	
    16	    private RequestParser() {}
    17	
    18	    static ReservationRequest reservation(String body) {
    19	        JsonNode json;
    20	        try {
    21	            json = MAPPER.readTree(body);
    22	        } catch (Exception e) {
    23	            throw ApiException.invalid("O corpo não é um JSON válido");
    24	        }
    25	        if (json == null || !json.isObject()) throw ApiException.invalid("O corpo deve ser um objeto JSON");
    26	
    27	        JsonNode roomNode = json.get("roomNumber");
    28	        JsonNode guestsNode = json.get("guests");
    29	        if (roomNode == null || !roomNode.isInt()) throw ApiException.invalid("roomNumber é obrigatório e deve ser inteiro");
    30	        if (guestsNode == null || !guestsNode.isInt()) throw ApiException.invalid("guests é obrigatório e deve ser inteiro");
    31	
    32	        String name = text(json, "guestName");
    33	        String email = text(json, "guestEmail");
    34	        String cpf = text(json, "guestCpf");
    35	        LocalDate checkIn = date(text(json, "checkIn"), "checkIn");
    36	        LocalDate checkOut = date(text(json, "checkOut"), "checkOut");
    37	        String plan = text(json, "ratePlan");
    38	
    39	        if (!checkOut.isAfter(checkIn)) throw ApiException.invalid("A saída deve ser depois da entrada");
    40	        if (guestsNode.asInt() < 1) throw ApiException.invalid("É preciso pelo menos um hóspede");
    41	
    42	        JsonNode company = json.get("companyCode");
    43	        String companyCode = company != null && company.isTextual() && !company.asText().isBlank()
    44	                ? company.asText().trim() : null;
    45	
    46	        return new ReservationRequest(roomNode.asInt(), name, email, cpf, checkIn, checkOut, guestsNode.asInt(),
    47	                plan, companyCode);
    48	    }
    49	
    50	    static LocalDate date(String value, String field) {
    51	        try {
    52	            return LocalDate.parse(value);
    53	        } catch (DateTimeParseException e) {
    54	            throw ApiException.invalid(field + " deve estar no formato AAAA-MM-DD");
    55	        }
    56	    }
    57	
    58	    static YearMonth month(String value) {
    59	        if (value == null || !value.matches("\\d{4}-\\d{2}")) throw ApiException.invalid("month deve estar no formato AAAA-MM");
    60	        try {
    61	            return YearMonth.parse(value);
    62	        } catch (DateTimeParseException e) {
    63	            throw ApiException.invalid("month deve estar no formato AAAA-MM");
    64	        }
    65	    }
    66	
    67	    private static String text(JsonNode json, String field) {
    68	        JsonNode node = json.get(field);
    69	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    70	            throw ApiException.invalid(field + " é obrigatório");
    71	        }
    72	        return node.asText();
    73	    }
    74	}
