     1	package br.com.mare.web;
     2	
     3	import br.com.mare.domain.ApiException;
     4	import br.com.mare.domain.ReportService;
     5	import br.com.mare.domain.ReservationService;
     6	import br.com.mare.domain.Rooms;
     7	import com.fasterxml.jackson.databind.ObjectMapper;
     8	import io.javalin.Javalin;
     9	import io.javalin.http.Context;
    10	
    11	import java.util.Map;
    12	
    13	public final class Routes {
    14	    private static final ObjectMapper MAPPER = new ObjectMapper();
    15	
    16	    private Routes() {}
    17	
    18	    public static Javalin register(Javalin app, ReservationService service, ReportService reports) {
    19	        app.get("/rooms", ctx -> json(ctx, 200, Rooms.all().stream().map(Views::room).toList()));
    20	        app.post("/reservations", ctx ->
    21	                json(ctx, 201, Views.reservation(service.create(RequestParser.reservation(ctx.body())))));
    22	        app.get("/reservations/{id}", ctx -> json(ctx, 200, Views.reservation(service.get(id(ctx)))));
    23	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, Views.reservation(service.confirm(id(ctx)))));
    24	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, Views.reservation(service.cancel(id(ctx)))));
    25	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, Views.reservation(service.checkIn(id(ctx)))));
    26	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, Views.receipt(service.checkOut(id(ctx)))));
    27	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, Views.receipt(service.document(id(ctx)))));
    28	        app.get("/messages", ctx -> json(ctx, 200, service.messages().stream().map(Views::message).toList()));
    29	        app.get("/reports/occupancy", ctx -> csv(ctx,
    30	                reports.occupancy(RequestParser.date(ctx.queryParam("date"), "date"))));
    31	        app.get("/reports/revenue", ctx -> csv(ctx, reports.revenue(RequestParser.month(ctx.queryParam("month")))));
    32	
    33	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status(), e.code(), e.getMessage()));
    34	        app.exception(Exception.class, (e, ctx) -> {
    35	            e.printStackTrace();
    36	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
    37	        });
    38	        return app;
    39	    }
    40	
    41	    private static int id(Context ctx) {
    42	        String raw = ctx.pathParam("id");
    43	        try {
    44	            return Integer.parseInt(raw);
    45	        } catch (NumberFormatException e) {
    46	            throw ApiException.reservationNotFound("Reserva " + raw + " não existe");
    47	        }
    48	    }
    49	
    50	    private static void json(Context ctx, int status, Object body) throws Exception {
    51	        ctx.status(status).contentType("application/json").result(MAPPER.writeValueAsString(body));
    52	    }
    53	
    54	    private static void csv(Context ctx, String body) {
    55	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
    56	    }
    57	
    58	    private static void error(Context ctx, int status, String code, String message) {
    59	        try {
    60	            json(ctx, status, Map.of("error", code, "message", message == null ? "" : message));
    61	        } catch (Exception e) {
    62	            ctx.status(status);
    63	        }
    64	    }
    65	}
